// Фикстура (b): случайные ноты вне лада.
//
// Максимальная «энтропия»: каждая нота случайна, ни одна не повторяется.
// Такой трек звучит как шум — и должен получить низкий балл по тональности,
// несмотря на высокое разнообразие.
//
// ВАЖНО: ноты заданы через `note("...")`, а не через `n(...).scale(key)`.
// Метод `.scale()` переводит ступень в ступень лада — то есть ГАРАНТИРУЕТ
// попадание в лад. Чтобы получить ноты вне лада, нужны буквенные имена.
//
// Форма у трека ЕСТЬ: четыре секции по 16 тактов с разной плотностью,
// переходы, автоматизация. Всё это должно выглядеть как «сложный трек» —
// но ноты вне лада обязаны его утопить.
//
// Настоящий код Strudel: ноты вне лада c:minor.

setCpm(120/4)
const key = "c:minor"

$KICK: arrange(
  [16, s("bd*4")],
  [16, s("bd*4 bd*2")],
  [16, s("bd*8")],
  [16, s("bd*2")],
).gain(0.9)._scope()

$HATS: arrange(
  [16, s("hh*8")],
  [16, s("hh*16")],
  [16, s("hh*8 ~ hh*4")],
  [16, s("hh*4")],
).gain(0.3)._scope()

$SNARE: arrange(
  [16, s("~ cp ~ cp")],
  [16, s("cp*2 ~ cp")],
  [16, s("~ cp ~ cp")],
  [16, s("sd ~ ~ cp")],
).gain(0.55)._scope()

// Ноты вне лада c:minor: c#4, e4 (ok), f#4, a#4, d5, b3, g#4, c5.
$MEL: arrange(
  [16, note("c#4 e4 f#4 a#4")],
  [16, note("d5 b3 g#4 c5")],
  [16, note("f#3 a#3 c#4 e4")],
  [16, note("g#4 c5 b4 e#5")],
).s("square").gain(0.5)._pianoroll()

$PAD: arrange(
  [16, note("d4 g#4 b3 f#4")],
  [16, note("c#4 e4 g#4 b4")],
  [16, note("f#3 a#3 c#4 e#4")],
  [16, note("g#3 b3 d4 g#4")],
).s("sawtooth").gain(0.3)._pianoroll()

$ARP: arrange(
  [16, note("c#5 e5 g#5 b4").fast(2)],
  [16, note("d5 f#5 a#5 c#5").fast(2)],
  [16, note("e#4 g#4 b4 d5").fast(4)],
  [16, note("f#4 a#4 c#5 e#5").fast(2)],
).s("square").gain(0.25)._pianoroll()

$LEAD: arrange(
  [16, note("e#5 c#5 a#4 f#4")],
  [16, note("b4 g#4 e#4 c#4")],
  [16, note("d5 a#4 f#4 c#4")],
  [16, note("e#4 b3 g#3 d4")],
).s("triangle").gain(0.4).room(0.3)._pianoroll()
